design.css:
/* Lavender: the anilili look (docs/theme-references/anilili-phone-parity.md). #050506 page, #101012
   surfaces, one #8979F2 accent, Roboto, Material filled icons (Google Material Icons, Apache-2.0).
   Phone sizes are dp from the app's Compose source at a 16 px root (1 CSS px = 1 dp). */

@keyframes lavender-nav-indicator {
  from { opacity: 0; transform: scaleX(0.5); }
  to { opacity: 1; transform: scaleX(1); }
}

/* ===== Shell: bottom navigation (M3 NavigationBar, MainActivity.kt:597-625) =====
   64 dp bar on #101012, four equal items 8 dp apart, a solid 64x32 accent indicator at y 4, the
   24 dp icon inside it, a 12/16 500 +0.5 label at y 40. It slides away with the app bar after 24 dp
   of downward scroll and returns after 24 dp up or 1 s idle (shell.bottomNav), over 220 ms. */
[data-slot="nav.bottom"][data-state] { gap: 8px; transition: transform 220ms cubic-bezier(0.4, 0, 0.2, 1); }
[data-slot="nav.bottom"] [data-part="nav.item"] { justify-content: flex-start; gap: 4px; min-width: 0; padding-top: 4px; }
[data-slot="nav.bottom"] [data-part="nav.item.icon"] { box-sizing: border-box; width: 64px; height: 32px; padding: 0; }
[data-slot="nav.bottom"] [data-part="nav.item.label"] { font-size: 12px; line-height: 16px; font-weight: 500; letter-spacing: 0.5px; white-space: nowrap; }
[data-slot="nav.bottom"] [data-part="nav.item"][data-active] [data-part="nav.item.icon"] { color: #f1f1f4; }
[data-slot="nav.bottom"] [data-part="nav.item"][data-active] [data-part="nav.item.icon"] > span:first-child { background: #8979f2 !important; }
:scope:not([data-motion="reduced"]) [data-slot="nav.bottom"] [data-part="nav.item"][data-active] [data-part="nav.item.icon"] > span:first-child { animation: lavender-nav-indicator 150ms cubic-bezier(0.2, 0, 0, 1); }
/* Material filled glyphs per destination (the bar and the Home app bar); other destinations keep izumi's. */
:is([data-slot="nav.bottom"] [data-part="nav.item"], [data-part="home.header.action"]):is([data-dest="home"], [data-dest="schedule"], [data-dest="library"], [data-dest="settings"], [data-dest="search"], [data-dest="downloads"]) svg { display: none; }
[data-slot="nav.bottom"] [data-part="nav.item"]:is([data-dest="home"], [data-dest="schedule"], [data-dest="library"], [data-dest="settings"], [data-dest="search"], [data-dest="downloads"]) [data-part="nav.item.icon"]::after,
[data-part="home.header.action"]:is([data-dest="home"], [data-dest="schedule"], [data-dest="library"], [data-dest="settings"], [data-dest="search"], [data-dest="downloads"])::after {
  content: "";
  position: relative;
  z-index: 1;
  width: 24px;
  height: 24px;
  background-color: currentColor;
  -webkit-mask-repeat: no-repeat;
  mask-repeat: no-repeat;
  -webkit-mask-position: center;
  mask-position: center;
  -webkit-mask-size: 24px 24px;
  mask-size: 24px 24px;
}
[data-slot="nav.bottom"] [data-part="nav.item"][data-dest="home"] [data-part="nav.item.icon"]::after, [data-part="home.header.action"][data-dest="home"]::after { -webkit-mask-image: url(data:image/svg+xml,%3Csvg%20xmlns=%27http://www.w3.org/2000/svg%27%20viewBox=%270%200%2024%2024%27%3E%3Cpath%20d=%27M10%2020v-6h4v6h5v-8h3L12%203%202%2012h3v8z%27/%3E%3C/svg%3E); mask-image: url(data:image/svg+xml,%3Csvg%20xmlns=%27http://www.w3.org/2000/svg%27%20viewBox=%270%200%2024%2024%27%3E%3Cpath%20d=%27M10%2020v-6h4v6h5v-8h3L12%203%202%2012h3v8z%27/%3E%3C/svg%3E); }
[data-slot="nav.bottom"] [data-part="nav.item"][data-dest="schedule"] [data-part="nav.item.icon"]::after, [data-part="home.header.action"][data-dest="schedule"]::after { -webkit-mask-image: url(data:image/svg+xml,%3Csvg%20xmlns=%27http://www.w3.org/2000/svg%27%20viewBox=%270%200%2024%2024%27%3E%3Cpath%20d=%27M9%2011H7v2h2v-2zm4%200h-2v2h2v-2zm4%200h-2v2h2v-2zm2-7h-1V2h-2v2H8V2H6v2H5c-1.11%200-1.99.9-1.99%202L3%2020c0%201.1.89%202%202%202h14c1.1%200%202-.9%202-2V6c0-1.1-.9-2-2-2zm0%2016H5V9h14v11z%27/%3E%3C/svg%3E); mask-image: url(data:image/svg+xml,%3Csvg%20xmlns=%27http://www.w3.org/2000/svg%27%20viewBox=%270%200%2024%2024%27%3E%3Cpath%20d=%27M9%2011H7v2h2v-2zm4%200h-2v2h2v-2zm4%200h-2v2h2v-2zm2-7h-1V2h-2v2H8V2H6v2H5c-1.11%200-1.99.9-1.99%202L3%2020c0%201.1.89%202%202%202h14c1.1%200%202-.9%202-2V6c0-1.1-.9-2-2-2zm0%2016H5V9h14v11z%27/%3E%3C/svg%3E); }
[data-slot="nav.bottom"] [data-part="nav.item"][data-dest="library"] [data-part="nav.item.icon"]::after, [data-part="home.header.action"][data-dest="library"]::after { -webkit-mask-image: url(data:image/svg+xml,%3Csvg%20xmlns=%27http://www.w3.org/2000/svg%27%20viewBox=%270%200%2024%2024%27%3E%3Cpath%20d=%27M3%2013h2v-2H3v2zm0%204h2v-2H3v2zm0-8h2V7H3v2zm4%204h14v-2H7v2zm0%204h14v-2H7v2zM7%207v2h14V7H7z%27/%3E%3C/svg%3E); mask-image: url(data:image/svg+xml,%3Csvg%20xmlns=%27http://www.w3.org/2000/svg%27%20viewBox=%270%200%2024%2024%27%3E%3Cpath%20d=%27M3%2013h2v-2H3v2zm0%204h2v-2H3v2zm0-8h2V7H3v2zm4%204h14v-2H7v2zm0%204h14v-2H7v2zM7%207v2h14V7H7z%27/%3E%3C/svg%3E); }
[data-slot="nav.bottom"] [data-part="nav.item"][data-dest="settings"] [data-part="nav.item.icon"]::after, [data-part="home.header.action"][data-dest="settings"]::after { -webkit-mask-image: url(data:image/svg+xml,%3Csvg%20xmlns=%27http://www.w3.org/2000/svg%27%20viewBox=%270%200%2024%2024%27%3E%3Cpath%20d=%27M19.14%2012.94c.04-.3.06-.61.06-.94%200-.32-.02-.64-.07-.94l2.03-1.58c.18-.14.23-.41.12-.61l-1.92-3.32c-.12-.22-.37-.29-.59-.22l-2.39.96c-.5-.38-1.03-.7-1.62-.94l-.36-2.54c-.04-.24-.24-.41-.48-.41h-3.84c-.24%200-.43.17-.47.41l-.36%202.54c-.59.24-1.13.57-1.62.94l-2.39-.96c-.22-.08-.47%200-.59.22L2.74%208.87c-.12.21-.08.47.12.61l2.03%201.58c-.05.3-.09.63-.09.94s.02.64.07.94l-2.03%201.58c-.18.14-.23.41-.12.61l1.92%203.32c.12.22.37.29.59.22l2.39-.96c.5.38%201.03.7%201.62.94l.36%202.54c.05.24.24.41.48.41h3.84c.24%200%20.44-.17.47-.41l.36-2.54c.59-.24%201.13-.56%201.62-.94l2.39.96c.22.08.47%200%20.59-.22l1.92-3.32c.12-.22.07-.47-.12-.61l-2.01-1.58zM12%2015.6c-1.98%200-3.6-1.62-3.6-3.6s1.62-3.6%203.6-3.6%203.6%201.62%203.6%203.6-1.62%203.6-3.6%203.6z%27/%3E%3C/svg%3E); mask-image: url(data:image/svg+xml,%3Csvg%20xmlns=%27http://www.w3.org/2000/svg%27%20viewBox=%270%200%2024%2024%27%3E%3Cpath%20d=%27M19.14%2012.94c.04-.3.06-.61.06-.94%200-.32-.02-.64-.07-.94l2.03-1.58c.18-.14.23-.41.12-.61l-1.92-3.32c-.12-.22-.37-.29-.59-.22l-2.39.96c-.5-.38-1.03-.7-1.62-.94l-.36-2.54c-.04-.24-.24-.41-.48-.41h-3.84c-.24%200-.43.17-.47.41l-.36%202.54c-.59.24-1.13.57-1.62.94l-2.39-.96c-.22-.08-.47%200-.59.22L2.74%208.87c-.12.21-.08.47.12.61l2.03%201.58c-.05.3-.09.63-.09.94s.02.64.07.94l-2.03%201.58c-.18.14-.23.41-.12.61l1.92%203.32c.12.22.37.29.59.22l2.39-.96c.5.38%201.03.7%201.62.94l.36%202.54c.05.24.24.41.48.41h3.84c.24%200%20.44-.17.47-.41l.36-2.54c.59-.24%201.13-.56%201.62-.94l2.39.96c.22.08.47%200%20.59-.22l1.92-3.32c.12-.22.07-.47-.12-.61l-2.01-1.58zM12%2015.6c-1.98%200-3.6-1.62-3.6-3.6s1.62-3.6%203.6-3.6%203.6%201.62%203.6%203.6-1.62%203.6-3.6%203.6z%27/%3E%3C/svg%3E); }
