[data-slot="nav.bottom"] [data-part="nav.item"][data-dest="downloads"] [data-part="nav.item.icon"]::after, [data-part="home.header.action"][data-dest="downloads"]::after { -webkit-mask-image: url(data:image/svg+xml,%3Csvg%20xmlns=%27http://www.w3.org/2000/svg%27%20viewBox=%270%200%2024%2024%27%3E%3Cpath%20d=%27M5%2020h14v-2H5v2zM19%209h-4V3H9v6H5l7%207%207-7z%27/%3E%3C/svg%3E); mask-image: url(data:image/svg+xml,%3Csvg%20xmlns=%27http://www.w3.org/2000/svg%27%20viewBox=%270%200%2024%2024%27%3E%3Cpath%20d=%27M5%2020h14v-2H5v2zM19%209h-4V3H9v6H5l7%207%207-7z%27/%3E%3C/svg%3E); }

/* ===== Phone Home (HomeScreen.kt) ===== */
@media (max-width: 640px) {
  /* App bar: M3 TopAppBar, 64 dp, #050506, pinned over the list; it slides out with the bottom bar.
     izumi's own mark and wordmark stay as they are; Search is the one action (48 dp, 24 dp glyph). */
  [data-slot="home.header"] {
    box-sizing: border-box;
    position: sticky;
    top: env(safe-area-inset-top, 0px);
    z-index: 25;
    display: flex;
    flex-direction: column;
    justify-content: center;
    min-height: 64px;
    margin-bottom: 0;
    padding: 0 4px 0 16px;
    background: #050506;
    box-shadow: 0 calc(-1 * env(safe-area-inset-top, 0px)) 0 0 #050506;
    transition: transform 220ms cubic-bezier(0.4, 0, 0.2, 1);
  }
  :scope[data-chrome="hidden"] [data-slot="home.header"] { transform: translateY(calc(-100% - env(safe-area-inset-top, 0px))); }
  [data-part="home.header.actions"] { gap: 0; }
  [data-part="home.header.action"] { width: 48px; height: 48px; color: #98989f; }
  [data-part="home.header.action"] svg { width: 24px; height: 24px; }

  /* Genre chips (HomeScreen.kt:505-538): a sideways row edge to edge, 16 dp content padding, gap 8;
     31.2 dp chips, 13 sp, a 1 dp #27272C @ 60 % rim on every chip; "All" filled with the accent. */
  [data-slot="block.genre-chips"] { margin: 0 0 14px; padding: 0; }
  [data-slot="block.genre-chips"] > div {
    flex-wrap: nowrap;
    gap: 8px;
    padding: 0 16px;
    overflow-x: auto;
    overflow-y: hidden;
    overscroll-behavior-x: contain;
    scrollbar-width: none;
  }
  [data-slot="block.genre-chips"] [data-part="chip"] {
    box-sizing: border-box;
    flex-shrink: 0;
    display: inline-flex;
    align-items: center;
    height: 31.2px;
    padding: 0 15px; /* + the 1 dp rim = 16: Compose draws the border inside the padding */
    border: 1px solid rgba(39, 39, 44, 0.6);
    border-radius: 999px;
    background: #101012;
    color: #98989f;
    font-size: 13px;
    line-height: 15px;
    font-weight: 600;
    letter-spacing: 0;
    white-space: nowrap;
  }
  [data-slot="block.genre-chips"] [data-part="chip"][data-active] { background: #8979f2; color: #f1f1f4; font-weight: 700; }

  /* Hero (HomeScreen.kt:578-923): full width x 270 dp, no radius, scrim 30 / 12 / 45 % black to #050506. */
  [data-slot="home.hero"][data-variant="template"] { height: 270px !important; min-height: 0; margin: 0 0 14px; }
  /* The scrim ends on 2 dp of solid #050506 and the art stops 1 dp short of the edge, so a hero bottom
     that falls mid-pixel never shows the art's last device pixel as a bright hairline. */
  [data-part="lavender.hero"]::after {
    content: "";
    position: absolute;
    inset: 0 0 -1px;
    z-index: 1;
    pointer-events: none;
    background: linear-gradient(to bottom, rgba(0, 0, 0, 0.3) 0%, rgba(0, 0, 0, 0.12) 42%, rgba(0, 0, 0, 0.45) 72%, #050506 100%) !important;
    box-shadow: inset 0 -2px 0 #050506;
  }
  [data-part="lavender.hero"] > [data-part="lavender.hero-art"] { clip-path: inset(0 0 1px 0); }
  /* HeroPill: black 42 %, 12x6 padding, 28 dp, no rim or blur, 14 dp from the top, 16 from the sides. */
  [data-part="lavender.hero"] > :is([data-part="lavender.chip"], [data-part="lavender.pager"]) {
    box-sizing: border-box;
    height: 28px;
    margin: 14px 16px;
    padding: 0 12px !important;
    border-radius: 999px;
    background: rgba(0, 0, 0, 0.42);
    color: #f1f1f4;
    font-size: 12px;
    line-height: 16px;
    font-weight: 600;
    letter-spacing: 0.5px;
    white-space: nowrap;
    overflow: hidden !important;
  }
  [data-part="lavender.chip"] > [data-part="lavender.cd-ep"] { margin-left: 5px; }
  [data-part="lavender.chip"] > [data-part="lavender.cd-no"] { margin-left: 3.5px; }
  [data-part="lavender.chip"] > [data-part="lavender.countdown"] { margin-left: 7px; text-transform: uppercase; }
  [data-part="lavender.pager"] > [data-part="lavender.slide"] { font-weight: 700; }
  [data-part="lavender.pager"] > :is([data-part="lavender.slash"], [data-part="lavender.slides"]) { color: rgba(255, 255, 255, 0.7); font-size: 11px; font-weight: 500; letter-spacing: 0; }
  [data-part="lavender.pager"] > [data-part="lavender.slash"] { margin: 0 2.7px; }
  /* Content column: bottom 26 dp (+ the 4 dp touch inset under 40 dp buttons), centred. */
  [data-part="lavender.hero"] > [data-part="lavender.info"] { padding: 0 16px 30px !important; gap: 0; text-align: center; }
  [data-part="lavender.info"] > [data-part="lavender.meta"] { max-width: 100%; color: #f1f1f4; font-size: 12px; line-height: 16px; font-weight: 600; letter-spacing: 0.5px; white-space: nowrap; overflow: hidden !important; }
  [data-part="lavender.meta"] > [data-part="lavender.meta-cell"] { overflow: visible !important; }
  [data-part="lavender.meta"] > [data-part="lavender.meta-cell"] + [data-part="lavender.meta-cell"]::before { content: "•"; margin: 0 8px; color: rgba(255, 255, 255, 0.45); font-weight: 500; letter-spacing: 0; }
  [data-part="lavender.info"] [data-part="lavender.title"] { margin-top: 10px; color: #fff; font-size: 28px; line-height: 34px; font-weight: 900; letter-spacing: 0; text-shadow: none !important; }
  /* Genre pill: the first three genres joined "  ·  ", labelMedium 500. */
  [data-part="lavender.info"] > [data-part="lavender.genres"] {
    box-sizing: border-box;
    max-width: 100%;
    height: 28px;
    margin-top: 12px;
    padding: 0 12px;
    gap: 6.9px;
    border-radius: 999px;
    background: rgba(0, 0, 0, 0.42);
    color: #f1f1f4;
    font-size: 12px;
    line-height: 16px;
    font-weight: 500;
    letter-spacing: 0.5px;
    white-space: nowrap;
    overflow: hidden !important;
  }
  /* Details (outlined, black 35 %, Info 18) + Watch Now (white, PlayArrow 20): 40 dp, 13 sp, gap 12. */
  [data-part="lavender.info"] > [data-part="lavender.actions"] { margin-top: 22px; gap: 12px; overflow: visible !important; }
  [data-part="lavender.actions"] > :is([data-part="lavender.details"], [data-part="lavender.watch"]) {
    box-sizing: border-box;
    flex-shrink: 0;
    height: 40px;
    min-height: 40px !important;
    padding: 0 24px !important;
    gap: 6px !important;
    border-radius: 999px !important;
    font-size: 13px;
    line-height: 15px;
    letter-spacing: 0;
    white-space: nowrap;
  }
  [data-part="lavender.actions"] > [data-part="lavender.details"] { border: 1px solid #27272c; background: rgba(0, 0, 0, 0.35) !important; color: #fff !important; font-weight: 600 !important; }
  [data-part="lavender.actions"] > [data-part="lavender.watch"] { border: 0; background: #fff !important; color: #000 !important; font-weight: 700 !important; }
  [data-part="lavender.actions"] > [data-part="lavender.watch"] svg { display: none; }
  [data-part="lavender.actions"] > :is([data-part="lavender.details"], [data-part="lavender.watch"])::before {
    content: "";
    flex-shrink: 0;
    width: 18px;
    height: 18px;
    background-color: currentColor;
    -webkit-mask: url(data:image/svg+xml,%3Csvg%20xmlns=%27http://www.w3.org/2000/svg%27%20viewBox=%270%200%2024%2024%27%3E%3Cpath%20d=%27M12%202C6.48%202%202%206.48%202%2012s4.48%2010%2010%2010%2010-4.48%2010-10S17.52%202%2012%202zm1%2015h-2v-6h2v6zm0-8h-2V7h2v2z%27/%3E%3C/svg%3E) center / 18px 18px no-repeat;
    mask: url(data:image/svg+xml,%3Csvg%20xmlns=%27http://www.w3.org/2000/svg%27%20viewBox=%270%200%2024%2024%27%3E%3Cpath%20d=%27M12%202C6.48%202%202%206.48%202%2012s4.48%2010%2010%2010%2010-4.48%2010-10S17.52%202%2012%202zm1%2015h-2v-6h2v6zm0-8h-2V7h2v2z%27/%3E%3C/svg%3E) center / 18px 18px no-repeat;
  }
  [data-part="lavender.actions"] > [data-part="lavender.watch"]::before {
    width: 20px;
    height: 20px;
    -webkit-mask: url(data:image/svg+xml,%3Csvg%20xmlns=%27http://www.w3.org/2000/svg%27%20viewBox=%270%200%2024%2024%27%3E%3Cpath%20d=%27M8%205v14l11-7z%27/%3E%3C/svg%3E) center / 20px 20px no-repeat;
    mask: url(data:image/svg+xml,%3Csvg%20xmlns=%27http://www.w3.org/2000/svg%27%20viewBox=%270%200%2024%2024%27%3E%3Cpath%20d=%27M8%205v14l11-7z%27/%3E%3C/svg%3E) center / 20px 20px no-repeat;
  }
  /* Meta-row and chip glyphs: Material ClosedCaption, Star (#EFC66B) and Schedule. */
  [data-part="lavender.hero"] :is([data-part="lavender.chip-clock"], [data-part="lavender.cc"], [data-part="lavender.star"], [data-part="lavender.clock"]) svg { display: none; }
  [data-part="lavender.hero"] :is([data-part="lavender.chip-clock"], [data-part="lavender.cc"], [data-part="lavender.star"], [data-part="lavender.clock"]) {
    flex-shrink: 0;
    width: 15px;
    height: 15px;
    margin-right: 3px;
    background-color: currentColor;
    -webkit-mask-repeat: no-repeat;
    mask-repeat: no-repeat;
    -webkit-mask-position: center;
    mask-position: center;
    -webkit-mask-size: 100% 100%;
    mask-size: 100% 100%;
  }
  [data-part="lavender.hero"] [data-part="lavender.chip-clock"] { width: 14px; height: 14px; margin-right: 0; }
