/* ===== Series page, phone (anilili DetailScreen.kt; docs/theme-references/anilili-phone-parity.md) =====
   One column under a solid 64 dp bar: a 190 dp banner, a 98x147 poster overlapping it by 61 dp, the
   title column, two equal 40 dp buttons, the Home / Episodes / Related pills, then the tab. Scoped to
   the phone page (not a width query) so landscape phones and tablets get the same page. */

@keyframes lavender-spin {
  to { transform: rotate(360deg); }
}
@keyframes lavender-arc {
  0% { border-right-color: transparent; border-bottom-color: transparent; }
  50% { border-right-color: #8979f2; border-bottom-color: transparent; }
  100% { border-right-color: transparent; border-bottom-color: transparent; }
}
@keyframes lavender-fade-in {
  from { opacity: 0; }
  to { opacity: 1; }
}

/* Opening a series is a 700 ms cross-fade in anilili (navigation-compose's default). No fill mode: once
   it ends the page is no stacking context, so the sheets it opens still layer as izumi's own. */
:scope:not([data-motion="reduced"]) [data-slot="detail"][data-variant="phone"] { animation: lavender-fade-in 700ms cubic-bezier(0.4, 0, 0.2, 1); }
